using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
namespace CreditMonitor.Insights {
 public sealed partial class HistoryStore {
  internal const string EventSource="(SELECT k,tool,provider,account,device,model,project,session,at,i,o,c,w,r,'event' AS granularity,1 AS requests FROM events UNION ALL SELECT k,tool,provider,account,device,model,project,session,at,i,o,c,w,r,granularity,requests FROM buckets)";
  internal static string Where(HistoryFilter filter,List<object> args){var f=filter??new HistoryFilter();args.Add(InsightIdentity.Time(f.From));args.Add(InsightIdentity.Time(f.To));string sql="at>=? AND at<?";var values=new[]{f.Tool,f.Model,f.Project,f.Device,f.Account};var columns=new[]{"tool","model","project","device","account"};for(int i=0;i<values.Length;i++)if(!String.IsNullOrEmpty(values[i])){sql+=" AND "+columns[i]+"=?";args.Add(values[i]);}return sql;}
  public Dictionary<string,List<string>> Choices(){using(var reader=OpenSnapshot()){var result=new Dictionary<string,List<string>>();foreach(string column in new[]{"tool","model","project","device","account"})result[column]=reader.Query("SELECT DISTINCT "+column+" value FROM (SELECT tool,model,project,device,account FROM event_minutes UNION ALL SELECT tool,model,project,device,account FROM buckets) ORDER BY value LIMIT 500").Select(r=>Convert.ToString(r["value"])).Where(v=>!String.IsNullOrEmpty(v)).ToList();return result;}}
  internal List<UsageEvent> DetailEvents(HistoryFilter filter,int limit){var parts=new List<string>();var args=new List<object>();foreach(string table in new[]{"events","buckets"}){string where=Where(filter,args);args.Add(limit);string tail=table=="events"?"'event' AS granularity,1 AS requests":"granularity,requests";parts.Add("SELECT * FROM (SELECT k,tool,provider,account,device,model,project,session,at,i,o,c,w,r,"+tail+" FROM "+table+" WHERE "+where+" ORDER BY at DESC LIMIT ?)");}args.Add(limit);return Query("SELECT * FROM ("+String.Join(" UNION ALL ",parts)+") ORDER BY at DESC LIMIT ?",args.ToArray()).Select(RowEvent).ToList();}
 }
 public sealed partial class InsightQueries {
  string CostSql(List<object> args){string sql="CASE";foreach(var p in prices.OrderByDescending(p=>p.EffectiveAt)){sql+=" WHEN model=? AND at>=? THEN ((i-c-w)*?+c*?+w*?+o*?)/1000000.0";args.AddRange(new object[]{p.Model,InsightIdentity.Time(p.EffectiveAt),p.Input,p.CachedInput,p.CacheWrite,p.Output});}return prices.Count==0?"NULL":sql+" ELSE NULL END";}
  string CurrencySql(List<object> args){string sql="CASE";foreach(var p in prices.OrderByDescending(p=>p.EffectiveAt)){sql+=" WHEN model=? AND at>=? THEN ?";args.AddRange(new object[]{p.Model,InsightIdentity.Time(p.EffectiveAt),p.Currency});}return prices.Count==0?"NULL":sql+" ELSE NULL END";}
  static long Long(Dictionary<string,object> row,string key){return row[key]==null?0:Convert.ToInt64(row[key]);}
  InsightSummary SqlSummary(HistoryFilter filter){var args=new List<object>();string where=HistoryStore.Where(filter,args);var r=store.Query("SELECT SUM(i+o) tokens,SUM(i) input,SUM(o) output,SUM(c) cache,SUM(requests) requests,COUNT(DISTINCT account||char(0)||tool||char(0)||session) sessions,NULL first,NULL last FROM "+AggregateSource(filter,true)+" WHERE "+where,args.ToArray())[0];var result=new InsightSummary{Tokens=Long(r,"tokens"),Input=Long(r,"input"),Output=Long(r,"output"),Cache=Long(r,"cache"),Requests=checked((int)Long(r,"requests")),Sessions=checked((int)Long(r,"sessions")),First=r["first"]==null?(DateTime?)null:DateTime.Parse((string)r["first"],CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind),Last=r["last"]==null?(DateTime?)null:DateTime.Parse((string)r["last"],CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind)};
   args.Clear();string cost=CostSql(args),currency=CurrencySql(args);where=HistoryStore.Where(filter,args);foreach(var row in store.Query("SELECT currency,SUM(cost) cost,SUM(CASE WHEN cost IS NULL THEN requests ELSE 0 END) unknown FROM (SELECT "+cost+" cost,"+currency+" currency,requests FROM "+AggregateSource(filter,true)+" WHERE "+where+") GROUP BY currency",args.ToArray())){if(row["currency"]==null)result.UnknownPriceRequests+=checked((int)Long(row,"unknown"));else result.Costs[(string)row["currency"]]=Convert.ToDouble(row["cost"]);}ExactEdges(result,filter);return result;
  }
  string SqlWeekly(DateTime until){string cutoff=InsightIdentity.Time(until.AddDays(-7));var row=store.Query("SELECT SUM(CASE WHEN at>=? THEN i+o ELSE 0 END) current,SUM(CASE WHEN at<? THEN i+o ELSE 0 END) prior,COUNT(DISTINCT CASE WHEN at>=? THEN account||char(0)||tool||char(0)||session ELSE NULL END) sessions FROM "+AggregateSource(new HistoryFilter{From=until.AddDays(-14),To=until},false,until.AddDays(-7))+" WHERE at>=? AND at<?",cutoff,cutoff,cutoff,InsightIdentity.Time(until.AddDays(-14)),InsightIdentity.Time(until))[0];long current=Long(row,"current"),prior=Long(row,"prior");string comparison=prior>0?((current-prior)*100.0/prior).ToString("+0.0;-0.0;0",CultureInfo.InvariantCulture)+"%":"ยังไม่มีฐานสัปดาห์ก่อน";return "7 วันล่าสุด: "+current.ToString("N0")+" tokens · "+Long(row,"sessions")+" sessions · เทียบช่วงก่อน "+comparison+" · ประวัติครอบคลุมเฉพาะ logs ที่พบ";}
  // Windows system SQLite can return NULL for its localtime modifier. Use .NET's
  // timezone rules to form UTC offset periods, including DST transitions, instead.
  internal static string CalendarShift(HistoryFilter filter,TimeZoneInfo zone){var f=filter??new HistoryFilter();DateTime cursor=f.From.ToUniversalTime(),end=f.To.ToUniversalTime();TimeSpan offset=zone.GetUtcOffset(cursor);string sql="CASE";while(cursor<end){DateTime next=cursor.AddHours(1);if(next>end)next=end;TimeSpan changed=zone.GetUtcOffset(next);if(changed!=offset){DateTime low=cursor,high=next;while(high.Ticks-low.Ticks>1){var middle=new DateTime(low.Ticks+(high.Ticks-low.Ticks)/2,DateTimeKind.Utc);if(zone.GetUtcOffset(middle)==offset)low=middle;else high=middle;}sql+=" WHEN at<'"+InsightIdentity.Time(high)+"' THEN '"+Modifier(offset)+"'";offset=changed;}cursor=next;}return sql=="CASE"?"'"+Modifier(offset)+"'":sql+" ELSE '"+Modifier(offset)+"' END";}
  static string Modifier(TimeSpan offset){return ((long)offset.TotalSeconds).ToString("+0;-0;0",CultureInfo.InvariantCulture)+" seconds";}
  List<InsightGroup> SqlGroup(HistoryFilter filter,string dimension,bool utc){string local=utc?"":","+CalendarShift(filter,TimeZoneInfo.Local);string hour=utc?"substr(at,12,2)":"strftime('%H',at"+local+")",label;
   switch(dimension){case "tool":case "project":case "device":case "account":case "session":label=dimension;break;case "day":label=utc?"substr(at,1,10)":"CASE WHEN granularity IN ('day','month') THEN substr(at,1,10) ELSE strftime('%Y-%m-%d',at"+local+") END";break;case "hour":label=hour;break;case "rhythm":label="CASE WHEN CAST("+hour+" AS INTEGER)<6 THEN '00–06' WHEN CAST("+hour+" AS INTEGER)<12 THEN '06–12' WHEN CAST("+hour+" AS INTEGER)<18 THEN '12–18' ELSE '18–24' END";break;default:label="model";break;}
   var args=new List<object>();bool priced=dimension!="day"&&dimension!="hour"&&dimension!="rhythm";string cost=priced?CostSql(args):"NULL",currency=priced?CurrencySql(args):"NULL",where=HistoryStore.Where(filter,args);if(dimension=="hour"||dimension=="rhythm")where+=" AND granularity IN ('event','hour','minute')";
   return store.Query("SELECT label,SUM(tokens) tokens,SUM(requests) requests,CASE WHEN SUM(CASE WHEN cost IS NULL OR currency<>'USD' THEN 1 ELSE 0 END)=0 THEN SUM(cost) ELSE NULL END cost FROM (SELECT "+label+" label,i+o tokens,requests,"+cost+" cost,"+currency+" currency FROM "+AggregateSource(filter,priced)+" WHERE "+where+") GROUP BY label ORDER BY tokens DESC",args.ToArray()).Select(r=>new InsightGroup{Label=(string)r["label"],Tokens=Long(r,"tokens"),Requests=checked((int)Long(r,"requests")),Cost=r["cost"]==null?(double?)null:Convert.ToDouble(r["cost"])}).ToList();
  }
 }
}
